    "hypothesis_id": 71,
    "feature": {
      "name": "any_comment_concrete_verifiable_example",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): any comment offers a concrete, locally verifiable example (specific instance with checkable particulars) in support of its counter-argument",
      "kind": "prompt",
      "spec": "Read the OC_comments JSON list (comments by users other than the OP). Return 1 if at least one comment, in its own voice, offers a concrete example of a specific, particular case (e.g., a specific named or otherwise identifiable person, event, place, policy, case, or personal/local situation with concrete details) whose particulars could be checked or observed directly, used to support its counter-argument. Purely abstract principles, generalities, hypotheticals without specific particulars, and vague appeals ('many people', 'in history') do not count. 'Locally verifiable' is not defined further; do not require external verification, just checkable specificity. Quoted OP text does not count. Return 0 if the list is valid and no comment qualifies (including an empty list). Return null if OC_comments is missing or malformed. Do not use other columns."
    }
  },
  {
    "hypothesis_id": 92,
    "feature": {
      "name": "all_comments_solely_abstract_logical_refutation",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): every comment relies solely on abstract logical refutation with no concrete external factual analogy",
      "kind": "prompt",
      "spec": "Read the OC_comments JSON list. Return 1 if the list is nonempty and every comment argues only through abstract logical reasoning/refutation (e.g. definitions, logical structure, general principles) and none introduces a concrete, external factual analogy based on a specific real-world case, event or fact. Return 0 if the list is valid and at least one comment introduces such a concrete analogy or other concrete external example. Return null if OC_comments is missing, malformed or empty. Use only OC_comments."
    }
  }
]

